// Golden-vector parity check: the Dart port must decide EXACTLY like the
// Python rule (vectors generated by fleet-management/tests/make_vectors.py).
// Run: dart run test/vectors_test.dart   (no package dependencies)

import 'dart:convert';
import 'dart:io';

import '../lib/gps_gate.dart';
import '../lib/stop_progress.dart';

int failures = 0;

void check(bool ok, String what) {
  if (!ok) {
    failures++;
    stderr.writeln('FAIL $what');
  }
}

void main() {
  final f = File.fromUri(Platform.script.resolve('vectors.json'));
  final v = jsonDecode(f.readAsStringSync()) as Map<String, dynamic>;
  var n = 0;
  for (final raw in v['progression'] as List) {
    final vec = raw as Map<String, dynamic>;
    final stops = (vec['stops'] as List).cast<Map>();
    final cfg = stopProgressConfig((vec['cfg'] as Map).cast<String, dynamic>());
    final st = newProgressState();
    final got = <List<Object?>>[];
    for (final fix in (vec['fixes'] as List).cast<Map>()) {
      for (final d in stepProgress(st, stops, fix, cfg)) {
        got.add([d['type'], d['stop_id'], d['status']]);
      }
    }
    final fixes = vec['fixes'] as List;
    for (final d in finalizeProgress(st, stops, (fixes.last as Map)['recorded_at'], cfg)) {
      got.add([d['type'], d['stop_id'], d['status']]);
    }
    final exp = (vec['expect']['decisions'] as List).map((e) => (e as List).toList()).toList();
    final sameLen = got.length == exp.length;
    var same = sameLen;
    for (var i = 0; same && i < got.length; i++) {
      same = got[i][0] == exp[i][0] && got[i][1] == exp[i][1] && got[i][2] == exp[i][2];
    }
    check(same, 'progression ${vec['name']}: decisions differ\n  dart:   $got\n  python: $exp');
    final statuses = stops.map((s) => ((st['stops'] as Map)[s['id']] as Map?)?['status']).toList();
    check(jsonEncode(statuses) == jsonEncode(vec['expect']['statuses']), 'progression ${vec['name']}: statuses $statuses vs ${vec['expect']['statuses']}');
    final summ = progressSummary(st, stops, cfg);
    final cl = (summ['stops'] as List).map((r) => (r as Map)['closest_m'] as num?).toList();
    final ecl = (vec['expect']['closest_m'] as List).cast<num?>();
    for (var i = 0; i < cl.length; i++) {
      final a = cl[i], b = ecl[i];
      check((a == null && b == null) || (a != null && b != null && (a - b).abs() <= 0.2),
          'progression ${vec['name']}: closest_m[$i] $a vs $b');
    }
    n++;
  }
  for (final raw in v['gate'] as List) {
    final vec = raw as Map<String, dynamic>;
    final start = vec['trip_started_at'] as String?;
    final gate = GpsGate(tripStartedAt: start == null ? null : DateTime.parse(start));
    final got = <String>[];
    for (final fix in (vec['fixes'] as List).cast<Map>()) {
      got.add(gate
          .check(
              lat: (fix['lat'] as num).toDouble(),
              lng: (fix['lng'] as num).toDouble(),
              recordedAt: DateTime.parse(fix['recorded_at'] as String),
              accuracy: (fix['accuracy'] as num?)?.toDouble())
          .toString());
    }
    final exp = (vec['expect'] as List).cast<String>();
    check(jsonEncode(got) == jsonEncode(exp), 'gate ${vec['name']}:\n  dart:   $got\n  python: $exp');
    n++;
  }
  if (failures == 0) {
    stdout.writeln('OK: $n golden vectors — the Dart port decides exactly like the server');
  } else {
    stdout.writeln('$failures failure(s) in $n vectors');
    exit(1);
  }
}
